SELECT Рабочий.NAME, Рабочий.YEAR, IIf(Рабочий!gaz>0,z(Рабочий!gaz)*100/z(Рабочий!B),0) AS GAZ, IIf(Доп_угли2015!gazpp>0,z(Доп_угли2015!gazpp)*100/z(Рабочий!B),0) AS gazpp, IIf(Рабочий!mazut>0,z(Рабочий!mazut)*100/z(Рабочий!B),0) AS MAZUT, IIf(Рабочий!torf>0,z(Рабочий!torf)*100/z(Рабочий!B),0) AS TORF, IIf(Рабочий!proch>0,z(Рабочий!proch)*100/z(Рабочий!B),0) AS PROCH, IIf(Рабочий!ugol>0,z(Рабочий!ugol)*100/z(Рабочий!B),0) AS UGOL, IIf(Рабочий!don>0,z(Рабочий!don)*100/z(Рабочий!B),0) AS DON, IIf(Рабочий!podm>0,z(Рабочий!podm)*100/z(Рабочий!B),0) AS PODM, IIf(Рабочий!pech>0,z(Рабочий!pech)*100/z(Рабочий!B),0) AS PECH, IIf(Доп_угли2015!vork>0,z(Доп_угли2015!vork)*100/z(Рабочий!B),0) AS vork, IIf(Доп_угли2015!int>0,z(Доп_угли2015!int)*100/z(Рабочий!B),0) AS intin, IIf(Рабочий!kuzn>0,z(Рабочий!kuzn)*100/z(Рабочий!B),0) AS KUZN, IIf(Доп_угли2015!kuzngd>0,z(Доп_угли2015!kuzngd)*100/z(Рабочий!B),0) AS kuzngd, IIf(Доп_угли2015!kuznt>0,z(Доп_угли2015!kuznt)*100/z(Рабочий!B),0) AS kuznt, IIf(Доп_угли2015!kuznss>0,z(Доп_угли2015!kuznss)*100/z(Рабочий!B),0) AS kuznss, IIf(Доп_угли2015!kuznun>0,z(Доп_угли2015!kuznun)*100/z(Рабочий!B),0) AS kuznun, IIf(Рабочий!ural>0,z(Рабочий!ural)*100/z(Рабочий!B),0) AS URAL, IIf(Доп_угли2015!sver>0,z(Доп_угли2015!sver)*100/z(Рабочий!B),0) AS sver, IIf(Доп_угли2015!chel>0,z(Доп_угли2015!chel)*100/z(Рабочий!B),0) AS chel, IIf(Доп_угли2015!kizel>0,z(Доп_угли2015!kizel)*100/z(Рабочий!B),0) AS kizel, IIf(Рабочий!bashk>0,z(Рабочий!bashk)*100/z(Рабочий!B),0) AS BASHK, IIf(Рабочий!kazah>0,z(Рабочий!kazah)*100/z(Рабочий!B),0) AS KAZAH, IIf(Доп_угли2015!ekib>0,z(Доп_угли2015!ekib)*100/z(Рабочий!B),0) AS ekib, IIf(Доп_угли2015!maikub>0,z(Доп_угли2015!maikub)*100/z(Рабочий!B),0) AS maikub, IIf(Рабочий!karag>0,z(Рабочий!karag)*100/z(Рабочий!B),0) AS KARAG, IIf(Рабочий!kan>0,z(Рабочий!kan)*100/z(Рабочий!B),0) AS KAN, IIf(Доп_угли2015!nazar>0,z(Доп_угли2015!nazar)*100/z(Рабочий!B),0) AS nazar, IIf(Доп_угли2015!ibor>0,z(Доп_угли2015!ibor)*100/z(Рабочий!B),0) AS ibor, IIf(Доп_угли2015!berez>0,z(Доп_угли2015!berez)*100/z(Рабочий!B),0) AS berez, IIf(Доп_угли2015!per>0,z(Доп_угли2015!per)*100/z(Рабочий!B),0) AS per, IIf(Доп_угли2015!irbei>0,z(Доп_угли2015!irbei)*100/z(Рабочий!B),0) AS irbei, IIf(Доп_угли2015!kansk>0,z(Доп_угли2015!kansk)*100/z(Рабочий!B),0) AS kansk, IIf(Рабочий!irkut>0,z(Рабочий!irkut)*100/z(Рабочий!B),0) AS IRKUT, IIf(Доп_угли2015!azey>0,z(Доп_угли2015!azey)*100/z(Рабочий!B),0) AS azey, IIf(Доп_угли2015!mug>0,z(Доп_угли2015!mug)*100/z(Рабочий!B),0) AS mug, IIf(Доп_угли2015!cher>0,z(Доп_угли2015!cher)*100/z(Рабочий!B),0) AS cher, IIf(Рабочий!tung>0,z(Рабочий!tung)*100/z(Рабочий!B),0) AS TUNG, IIf(Доп_угли2015!jer>0,z(Доп_угли2015!jer)*100/z(Рабочий!B),0) AS jer, IIf(Доп_угли2015!karab>0,z(Доп_угли2015!karab)*100/z(Рабочий!B),0) AS karab, IIf(Рабочий!hak>0,z(Рабочий!hak)*100/z(Рабочий!B),0) AS HAK, IIf(Рабочий!tuv>0,z(Рабочий!tuv)*100/z(Рабочий!B),0) AS TUV, IIf(Рабочий!bur>0,z(Рабочий!bur)*100/z(Рабочий!B),0) AS BUR, IIf(Доп_угли2015!gusin>0,z(Доп_угли2015!gusin)*100/z(Рабочий!B),0) AS gusin, IIf(Доп_угли2015!tugn>0,z(Доп_угли2015!tugn)*100/z(Рабочий!B),0) AS tugn, IIf(Доп_угли2015!okino>0,z(Доп_угли2015!okino)*100/z(Рабочий!B),0) AS okino, IIf(Рабочий!chit>0,z(Рабочий!chit)*100/z(Рабочий!B),0) AS CHIT, IIf(Доп_угли2015!har>0,z(Доп_угли2015!har)*100/z(Рабочий!B),0) AS har, IIf(Доп_угли2015!urt>0,z(Доп_угли2015!urt)*100/z(Рабочий!B),0) AS urt, IIf(Доп_угли2015!tataur>0,z(Доп_угли2015!tataur)*100/z(Рабочий!B),0) AS tataur, IIf(Доп_угли2015!tarbag>0,z(Доп_угли2015!tarbag)*100/z(Рабочий!B),0) AS tarbag, IIf(Доп_угли2015!zab_kam>0,z(Доп_угли2015!zab_kam)*100/z(Рабочий!B),0) AS zab_kam, IIf(Рабочий!amur>0,z(Рабочий!amur)*100/z(Рабочий!B),0) AS AMUR, IIf(Доп_угли2015!rai>0,z(Доп_угли2015!rai)*100/z(Рабочий!B),0) AS rai, IIf(Доп_угли2015!erk>0,z(Доп_угли2015!erk)*100/z(Рабочий!B),0) AS erk, IIf(Рабочий!urg>0,z(Рабочий!urg)*100/z(Рабочий!B),0) AS URG, IIf(Рабочий!ushum>0,z(Рабочий!ushum)*100/z(Рабочий!B),0) AS USHUM, IIf(Рабочий!prim>0,z(Рабочий!prim)*100/z(Рабочий!B),0) AS PRIM, IIf(Доп_угли2015!bikin>0,z(Доп_угли2015!bikin)*100/z(Рабочий!B),0) AS bikin, IIf(Доп_угли2015!razdol>0,z(Доп_угли2015!razdol)*100/z(Рабочий!B),0) AS razdol, IIf(Доп_угли2015!hankai>0,z(Доп_угли2015!hankai)*100/z(Рабочий!B),0) AS hankai, IIf(Рабочий!yakut>0,z(Рабочий!yakut)*100/z(Рабочий!B),0) AS YAKUT, IIf(Доп_угли2015!neru>0,z(Доп_угли2015!neru)*100/z(Рабочий!B),0) AS neru, IIf(Доп_угли2015!zyryan>0,z(Доп_угли2015!zyryan)*100/z(Рабочий!B),0) AS zyryan, IIf(Доп_угли2015!pyak>0,z(Доп_угли2015!pyak)*100/z(Рабочий!B),0) AS pyak, IIf(Рабочий!mag>0,z(Рабочий!mag)*100/z(Рабочий!B),0) AS MAG, IIf(Рабочий!chukot>0,z(Рабочий!chukot)*100/z(Рабочий!B),0) AS CHUKOT, IIf(Доп_угли2015!anad>0,z(Доп_угли2015!anad)*100/z(Рабочий!B),0) AS anad, IIf(Доп_угли2015!bering>0,z(Доп_угли2015!bering)*100/z(Рабочий!B),0) AS bering, IIf(Рабочий!kamch>0,z(Рабочий!kamch)*100/z(Рабочий!B),0) AS KAMCH, IIf(Рабочий!sah>0,z(Рабочий!sah)*100/z(Рабочий!B),0) AS SAH, Рабочий.NUMB1120, Рабочий.numb1 INTO Структура_топлива2015
FROM (Рабочий LEFT JOIN Доп_угли2015 ON (Рабочий.YEAR=Доп_угли2015.YEAR) AND (Рабочий.NUMB1120=Доп_угли2015.NUMB1120)) INNER JOIN Имена_станций ON Рабочий.NUMB1120=Имена_станций.NUMB
ORDER BY Рабочий.numb1;
